$\begin{array}{|l|l|}
\hline \begin{array}{l} 
\text{Cartilaginous} \\
\text{Joint}
\end{array} & \begin{array}{l} 
\text{- This is a type of amphiarthrosis or imperfectly movable joint.} \\
\text{- Between adjacent vertebrae in vertebral column such joints are} \\
\text{present. This allows little movement.}
\end{array} \\
\hline \begin{array}{l} 
\text{Ball and} \\
\text{Socket Joint}
\end{array} & \begin{array}{l} 
\text{- This is a synovial joint.} \\
\text{- This allows complete movement of the bones articulating.} \\
\text{- Between Humerus and Pectoral girdle such joint is found.} \\
\text{This joint allows multi-axial movement.}
\end{array} \\
\hline \text{Fibrous Joint} & \begin{array}{l} 
\text{- They are non-movable joints.} \\
\text{- They are found between flat skull bones.}
\end{array} \\
\hline \text{Saddle Joint} & \begin{array}{l} 
\text{- This is also a type of synovial joint.} \\
\text{- This is found in between carpal and metacarpal of thumb.}
\end{array} \\
\hline
\end{array}$

\(\begin{array}{|l|l|}
\hline \begin{array}{l}
\text { Vasectomy }
\end{array} & \begin{array}{l}
\text { - Sterilisation is a terminal contraception method. } \\
\text { - The vas deference is cut or tied to prevent the sperms to reach the vagina. }
\end{array} \\
\hline \begin{array}{l}
\text { Coitus } \\
\text { interruptus }
\end{array} & \begin{array}{l}
\text { - Withdrawal method is a natural contraception method in which the male partner } \\
\text { withdraws his penis from the vagina just before ejaculation to avoid insemination. }
\end{array} \\
\hline \begin{array}{l}
\text { Cervical } \\
\text { caps }
\end{array} & \begin{array}{l}
\text { - Diaphragms, cervical caps and vaults are also barriers made of rubber that are inserted } \\
\text { into the female reproductive tract to cover the cervix during coitus. }
\end{array} \\
\hline \text { Saheli } & \begin{array}{l}
\text { - This is the oral contraceptive for the females contains a non-steroidal preparation. }
\end{array} \\
\hline
\end{array}\)
